import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
    };

    Deno.serve(async (req) => {
      if (req.method === "OPTIONS") {
          return new Response("ok", { headers: corsHeaders });
            }

              const json = (status: number, body: unknown) =>
                  new Response(JSON.stringify(body), {
                        status,
                              headers: {
                                      ...corsHeaders,
                                              "Content-Type": "application/json",
                                                    },
                                                        });

                                                          try {
                                                              const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
                                                                  const SUPABASE_ANON_KEY = Deno.env.get("SUPABASE_ANON_KEY")!;
                                                                      const SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;

                                                                          const authHeader = req.headers.get("Authorization") || "";

                                                                              if (!authHeader.startsWith("Bearer ")) {
                                                                                    return json(401, { error: "Sesión no autorizada." });
                                                                                        }

                                                                                            const userClient = createClient(SUPABASE_URL, SUPABASE_ANON_KEY, {
                                                                                                  global: {
                                                                                                          headers: {
                                                                                                                    Authorization: authHeader,
                                                                                                                            },
                                                                                                                                  },
                                                                                                                                      });

                                                                                                                                          const service = createClient(SUPABASE_URL, SERVICE_ROLE_KEY);

                                                                                                                                              const { data: userData, error: userError } =
                                                                                                                                                    await userClient.auth.getUser();

                                                                                                                                                        if (userError || !userData?.user) {
                                                                                                                                                              return json(401, { error: "No se pudo verificar la sesión." });
                                                                                                                                                                  }

                                                                                                                                                                      const { data: accessContext, error: accessError } = await userClient.rpc("varelia_access_context");
 if (accessError || accessContext?.allowed !== true) return json(403, { error: "Cuenta sin acceso. Contacta al administrador principal." });
 const ownerId = userData.user.id;

                                                                                                                                                                          const { data: owner, error: ownerError } = await service
                                                                                                                                                                                .from("profiles")
                                                                                                                                                                                      .select("id,business_id,role")
                                                                                                                                                                                            .eq("id", ownerId)
                                                                                                                                                                                                  .maybeSingle();

                                                                                                                                                                                                      if (ownerError || !owner?.business_id) {
                                                                                                                                                                                                            return json(403, { error: "La cuenta no tiene un negocio válido." });
                                                                                                                                                                                                                }

                                                                                                                                                                                                                    if (owner.role !== "owner") {
                                                                                                                                                                                                                          return json(403, {
                                                                                                                                                                                                                                  error: "Solo el propietario puede administrar vendedores.",
                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                const body = await req.json().catch(() => ({}));
                                                                                                                                                                                                                                                    const action = String(body?.action || "");

                                                                                                                                                                                                                                                        if (action === "list") {
                                                                                                                                                                                                                                                              const { data, error } = await service
                                                                                                                                                                                                                                                                      .from("profiles")
                                                                                                                                                                                                                                                                              .select("id,full_name,role,permissions,business_id")
                                                                                                                                                                                                                                                                                      .eq("business_id", owner.business_id)
                                                                                                                                                                                                                                                                                              .neq("id", ownerId)
                                                                                                                                                                                                                                                                                                      .eq("role", "cashier");

                                                                                                                                                                                                                                                                                                            if (error) throw error;

                                                                                                                                                                                                                                                                                                                  const rows = data || [];
const sellers = await Promise.all(rows.map(async (seller) => {
  const { data: authData } = await service.auth.admin.getUserById(seller.id);
  return { ...seller, name: seller.full_name || "Vendedor", email: authData?.user?.email || "" };
}));
return json(200, { sellers });
                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                        if (action === "create") {
                                                                                                                                                                                                                                                                                                                                              const name = String(body?.name || "").trim();
                                                                                                                                                                                                                                                                                                                                                    const email = String(body?.email || "").trim().toLowerCase();
                                                                                                                                                                                                                                                                                                                                                          const password = String(body?.password || "");
                                                                                                                                                                                                                                                                                                                                                                const permissions =
                                                                                                                                                                                                                                                                                                                                                                        body?.permissions && typeof body.permissions === "object"
                                                                                                                                                                                                                                                                                                                                                                                  ? body.permissions
                                                                                                                                                                                                                                                                                                                                                                                            : {};

                                                                                                                                                                                                                                                                                                                                                                                                  if (!name) {
                                                                                                                                                                                                                                                                                                                                                                                                          return json(400, { error: "Ingresa el nombre del vendedor." });
                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                      if (!email || !email.includes("@")) {
                                                                                                                                                                                                                                                                                                                                                                                                                              return json(400, { error: "Ingresa un correo válido." });
                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                          if (password.length < 6) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                  return json(400, {
                                                                                                                                                                                                                                                                                                                                                                                                                                                            error: "La contraseña debe tener al menos 6 caracteres.",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const { data: created, error: createError } =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        await service.auth.admin.createUser({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  email,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            password,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      email_confirm: true,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                user_metadata: {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            full_name: name,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        varelia_account_type: "seller",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    varelia_owner_id: ownerId,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                varelia_business_id: owner.business_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (createError || !created?.user) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return json(400, {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          error: createError?.message || "No se pudo crear el vendedor.",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const sellerId = created.user.id;

    // El acceso solo se considera creado cuando su perfil quedó ligado al negocio.

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const { error: profileError } = await service
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .from("profiles")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .upsert(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          id: sellerId,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      full_name: name,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              business_id: owner.business_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          role: "cashier",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      permissions,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          { onConflict: "id" }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (profileError) {
        await service.auth.admin.deleteUser(sellerId);
        throw new Error(`No se pudo preparar el acceso del vendedor: ${profileError.message}`);
      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return json(200, {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ok: true,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            seller: {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      id: sellerId,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                name,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          email,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    role: "cashier",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              permissions,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (action === "update") {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const sellerId = String(body?.sellerId || "").trim();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const name = String(body?.name || "").trim();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const permissions =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              body?.permissions && typeof body.permissions === "object"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ? body.permissions
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  : {};

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const { data: seller } = await service
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                .from("profiles")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .select("id,business_id,role")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                .eq("id", sellerId)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .maybeSingle();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      !seller ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              String(seller.business_id) !== String(owner.business_id) ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      seller.role === "owner"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return json(404, {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              error: "No se encontró ese vendedor en tu negocio.",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const { error } = await service
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          .from("profiles")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  .update({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            full_name: name || "Vendedor",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      business_id: owner.business_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                role: "cashier",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          permissions,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  })
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          .eq("id", sellerId);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (error) throw error;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return json(200, { ok: true });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (action === "delete") {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const sellerId = String(body?.sellerId || "").trim();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const { data: seller } = await service
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  .from("profiles")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          .select("id,business_id,role")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  .eq("id", sellerId)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          .maybeSingle();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        !seller ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                String(seller.business_id) !== String(owner.business_id) ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        seller.role === "owner"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return json(404, {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                error: "No se encontró ese vendedor en tu negocio.",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const { error } =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            await service.auth.admin.deleteUser(sellerId);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (error) throw error;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return json(200, { ok: true });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return json(400, {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      error: "Acción no válida.",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            } catch (e: any) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return json(500, {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      error: e?.message || "Error interno de Varelia.",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });